mapper.select:
        select
        foodComment.*,
        users.nick_name,
        users.head_img,
        foods.food_name,
        foods.banner_img
        from food_comment foodComment
        left join users users on foodComment.user_id = users.id
		left join foods foods on foodComment.foods_id = foods.id

            and foodComment.id = #{id}
            and foodComment.content = #{content}
            and foodComment.user_id = #{userId}
            and foodComment.foods_id = #{foodsId}
            and foodComment.score = #{score}
            and foodComment.create_time = #{createTime}
            and foodComment.to_user_id = #{toUserId}
            and foodComment.parent_id = #{parentId}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
            and foods.food_name like concat('%',#{foodName},'%')
            and foods.banner_img = #{bannerImg}


            limit #{current},#{pageSize}

        select count(*) from food_comment foodComment
        left join users users on foodComment.user_id = users.id
		left join foods foods on foodComment.foods_id = foods.id

